      { k: 'trap', t: 'Нийлбэр биш, үржвэр',
        bad: { m: '\\ln 14+\\ln\\dfrac{1}{14}=\\ln\\left(14+\\dfrac{1}{14}\\right)', n: 'Нийлбэрийн логарифм гэсэн чанар байхгүй.' },
        good: { m: '\\ln 14+\\ln\\dfrac{1}{14}=\\ln\\left(14\\cdot\\dfrac{1}{14}\\right)=\\ln 1=0', n: 'Логарифмуудын нийлбэр $=$ үржвэрийн логарифм.' } },
      { k: 'check', q: '$y=e^{x}$ бол $x=\\ln 6$ үед $y$ хэд вэ?', o: ['$e^{6}$', '$6$', '$\\ln 6$', '$1$'], c: 1, why: '$e^{\\ln 6}=6$ — $e$ ба $\\ln$ бие биенээ устгана.' },
      { k: 'sum', pts: ['$e\\approx 2.718$; $\\ln x=\\log_{e}x$.', '$e^{\\ln a}=a$, $\\ln e^{a}=a$, $\\ln e=1$, $\\ln 1=0$.',
        '$e^{x}>0$ ба өсөх функц; $\\ln x$ нь $x>0$ үед тодорхойлогдох, өсөх функц.', 'Графикууд нь $y=x$ шулууны хувьд тэгш хэмтэй.'] }
